package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;
import java.util.*;
final class CustomerCasesBrowserAcceptance {
 static void click(Page page,String label){page.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName(label).setExact(true)).press("Enter");}
 static void run(BrowserTest h)throws Exception{
  String group;try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.createAccount(db,map("name","CustomerBrowserRequester","role","requester","password",WorkflowSupport.PASSWORD));Service.createAccount(db,map("name","CustomerBrowserStaff","role","agent","password",WorkflowSupport.PASSWORD));group=Service.create(db,"sys_user_group",map("short_description","Customer response team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,RecordAccess.owner(db,"CustomerBrowserStaff"));db.connection.commit();}
  try(var p=Playwright.create();var browser=p.chromium().launch();var adminContext=browser.newContext();var customerContext=browser.newContext();var staffContext=browser.newContext()){
   var admin=adminContext.newPage();h.login(admin,"admin");admin.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer accounts").setExact(true)).press("Enter");admin.getByLabel("Account name").fill("Customer shop <script>");admin.getByLabel("Support team").selectOption(group);click(admin,"Create customer account");String accountUrl=admin.url();admin.getByLabel("Contact username").fill("CustomerBrowserRequester");click(admin,"Find customer contact");assertThat(admin.locator("main")).containsText("Unassigned");click(admin,"Save customer contact");assertThat(admin.locator("main")).containsText("CustomerBrowserRequester · Active contact");admin.locator("#new-entitlement summary").press("Enter");var form=admin.locator("#new-entitlement");form.getByLabel("Entitlement name").fill("Business support");form.getByLabel("Support description").fill("Customer checkout and account support");form.getByLabel("Starts at (UTC)").fill("2020-01-01T00:00:00Z");form.getByLabel("Ends at (UTC)").fill("2099-01-01T00:00:00Z");form.getByLabel("Case limit").fill("2");form.getByRole(AriaRole.BUTTON,new Locator.GetByRoleOptions().setName("Create support entitlement").setExact(true)).press("Enter");var existing=admin.locator("section[id^='entitlement-']");existing.getByLabel("Support description").fill("Reviewed checkout and account support");click(admin,"Save entitlement: Business support");ReleaseBrowserAcceptance.accessible(admin);admin.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-account-light.png")).setFullPage(true));assertThat(admin.locator("main script")).hasCount(0);
   var customer=customerContext.newPage();customer.navigate(h.base()+"/login");customer.getByLabel("Username").fill("CustomerBrowserRequester");customer.getByLabel("Password",new Page.GetByLabelOptions().setExact(true)).fill(WorkflowSupport.PASSWORD);customer.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Enter your workspace")).press("Enter");customer.waitForURL("**/requests");customer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer service").setExact(true)).press("Enter");customer.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Business support")).press("Enter");assertThat(customer.locator("main")).containsText("2 case units currently remaining");assertThat(customer.locator(".breadcrumb")).containsText("Customer service");customer.getByLabel("Case summary").fill("Customer checkout unavailable <script>");customer.getByLabel("How can we help?").fill("Checkout fails for our registered shop");for(String theme:List.of("light","dark")){if(theme.equals("dark")){click(customer,"Dark mode");customer.setViewportSize(390,844);}ReleaseBrowserAcceptance.accessible(customer);customer.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-intake-"+theme+".png")).setFullPage(true));}click(customer,"Submit customer case");customer.waitForURL("**/record/customer_case/*");String caseUrl=customer.url();assertThat(customer.locator("main")).containsText("Customer support agreement");assertThat(customer.locator("main")).containsText("Business support");assertThat(customer.locator("main script")).hasCount(0);customer.getByLabel("Add a comment").fill("This is affecting our whole shop");click(customer,"Post comment");assertThat(customer.locator("main")).containsText("This is affecting our whole shop");
   var staff=staffContext.newPage();h.login(staff,"CustomerBrowserStaff");staff.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer service").setExact(true)).press("Enter");staff.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Customer checkout unavailable <script>").setExact(true)).press("Enter");staff.getByLabel("State").selectOption("working");click(staff,"Save changes →");assertThat(staff.locator("main")).containsText("In progress");customer.reload();assertThat(customer.locator("main")).containsText("In progress");
   admin.navigate(accountUrl);admin.getByLabel("Account availability").selectOption("false");click(admin,"Save customer account");customer.navigate(caseUrl);assertThat(customer.locator("main")).containsText("Record not found");admin.getByLabel("Account availability").selectOption("true");click(admin,"Save customer account");customer.navigate(caseUrl);assertThat(customer.locator("main")).containsText("Business support");ReleaseBrowserAcceptance.accessible(customer);customer.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/customer-case-dark.png")).setFullPage(true));
  }
 }
}
